# Tamil/English original packs live in i18n.py and are intentionally not
# duplicated here.

LANGUAGE_DTMF = {meta["dtmf"]: code for code, meta in LANGUAGES.items()}


def language_options() -> list[dict]:
    return [{"code": code, **meta} for code, meta in LANGUAGES.items()]


def is_supported_language(code: str | None) -> bool:
    return bool(code and code in LANGUAGES)


def speech_locale(code: str | None) -> str:
    return LANGUAGES.get(code or "en", LANGUAGES["en"])["locale"]


def greeting(code: str) -> str:
    if code == "ta": return "வணக்கம்"
    if code == "en": return "Welcome"
    return (CORE_LANGUAGE_PACKS.get(code, {}).get("welcome") or ["Welcome to FarmDirect."])[0]


def resolve_language_selection(dtmf: str | None = None, text: str | None = None) -> Optional[str]:
    d = (str(dtmf).strip() if dtmf is not None else "")
    if d in LANGUAGE_DTMF:
        return LANGUAGE_DTMF[d]
    raw = (text or "").strip().lower()
    if not raw:
        return None
    for code, meta in LANGUAGES.items():
        english = meta["english"].lower()
        native = meta["native"].lower()
        if english in raw or native in raw or raw == code:
            return code
    return None


def language_menu_prompt(lang: str = "en") -> list[str]:
    # Keep the spoken menu compact but complete. The simulator has a visual
    # picker; this two-digit list makes the same set reachable on real DTMF.
    entries = ", ".join(f"{m['dtmf']} {m['english']}" for m in LANGUAGES.values())
    if lang == "ta":
        return ["மொழியை தேர்வு செய்ய இரண்டு இலக்க குறியீட்டை உள்ளிடுங்கள்.", entries]
    if lang == "hi":
        return ["भाषा चुनने के लिए दो अंकों का कोड दर्ज करें।", entries]
    return ["Choose your language. Enter the two-digit language code.", entries]
